\set ON_ERROR_STOP on

create table if not exists feature_text_backup_2026_10_23_b as
 select 'class_features'::text t, id, name, description from class_features where name ilike '%hunter''s mark%' or description ilike '%hunter''s mark%' or description ilike '%prey brand%'
 union all select 'subclass_features', id, name, description from subclass_features where name ilike '%hunter''s mark%' or description ilike '%hunter''s mark%' or description ilike '%prey brand%';
create table if not exists items_backup_2026_10_23 as select * from items where id between 61 and 90;
create table if not exists spells_backup_2026_10_23_preamble as select * from spells;

begin;
update spells set name='Mark of the Hunter' where id=278 and name in ('Prey Brand','Hunter''s Mark');
update class_features set name=replace(name,'Hunter''s Mark','Mark of the Hunter'), description=replace(replace(description,'Hunter''s Mark','Mark of the Hunter'),'Prey Brand','Mark of the Hunter') where name ilike '%hunter''s mark%' or description ilike '%hunter''s mark%' or description ilike '%prey brand%';
update subclass_features set name=replace(name,'Hunter''s Mark','Mark of the Hunter'), description=replace(replace(description,'Hunter''s Mark','Mark of the Hunter'),'Prey Brand','Mark of the Hunter') where name ilike '%hunter''s mark%' or description ilike '%hunter''s mark%' or description ilike '%prey brand%';
update items set name='Scroll of Kindled Light', description='Read aloud to cast Lanternkiss (level 0) without a slot. The scroll crumbles after use.' where id=61 and description='Read aloud to cast Light (level 0) without a slot. The scroll crumbles after use.';
